return JSON.stringify({
  upload: 'POST https://n8n.rainforest.tools/webhook/inbox/<target> (LAN: http://<mac-mini>:5678/webhook/inbox/<target>), multipart/form-data with one file per request. From outside the LAN the request needs the Cloudflare Access service-token headers.',
  folder: 'Or drop the file into iCloud Drive Inbox/<target>/ ; it is picked up within about 2 minutes.',
  targets: [
    { target: 'bujo', accepts: 'Bullet Journal page photos or scans (jpeg, png, heic, webp)', fields: { notebook: 'physical notebook name; created if new. Folder form: Inbox/bujo/<notebook>/' }, result: 'appended to the notebook in personal-calibre; read back with the calibre MCP tools list_notebooks / get_notebook_pages' },
    { target: 'voice', accepts: 'audio (m4a, mp3, aiff, wav)', fields: {}, result: 'transcribed with Whisper into an Obsidian note under Voice memos/' },
    { target: 'memories', accepts: 'LINE chat exports (folder only: Inbox/memories/)', fields: {}, result: 'imported by the memories auto-import job on the Mac, not by n8n' },
  ],
  notes: 'Files are never passed as tool arguments. A file that fails three times is skipped and reported as inbox_rejected in the Obsidian daily note; rename it to retry.',
}, null, 2);
